import codecs
class Fault(KeyError):
    pass
failure = Fault('mapping failed')
events = []
class Mapping:
    def __getitem__(self, key):
        events.append(('mapping', key))
        print('mapping', key, flush=True)
        raise failure
def recover(error):
    events.append(('recovery', error.start, error.end))
    print('recovery', error.start, error.end, flush=True)
    return (b'?', -0)
# Return to the end using a negative position against a two-item input.
def resume(error):
    replacement, unused = recover(error)
    return replacement, -1 if error.end == 1 else 2
codecs.register_error('classification_audit', resume)
try:
    result = codecs.charmap_encode('AB', 'classification_audit', Mapping())
except Fault as caught:
    assert caught is failure
    print('failure', type(caught).__name__, caught.args)
else:
    print('result', result)
print(events)

