import fs from 'node:fs';
import assert from 'node:assert/strict';
import {PythonSession} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/index.ts';
const oracle=JSON.parse(fs.readFileSync('/tmp/charmap-classification-oracle.json','utf8'));
const results=[];
let realWrites=0,realReads=0;
for(const row of oracle.cases){
  const file='/tmp/charmap-classification-output.txt';
  const run=(cancelAt?:number)=>{
    const fd=fs.openSync(file,'w+'),controller=new AbortController();
    const events:string[]=[];
    const session=new PythonSession({limits:{maxSteps:1000000,maxAllocatedBytes:16000000,maxDepth:100},hashSeed:[1n,2n],signal:controller.signal,
      output:{write(text){fs.writeSync(fd,text);realWrites++;events.push(text);if(events.length===cancelAt)controller.abort();},flush(){fs.fsyncSync(fd);}}});
    try{
      const result=session.exec(row.source);
      if(cancelAt===undefined)assert.equal(result.status,'ok',JSON.stringify(result));
      else{
        assert.deepEqual(result,{status:'terminated',reason:'cancelled',message:'execution cancelled'});
        const count=events.length;
        assert.deepEqual(session.exec("print('continued')"),{status:'terminated',reason:'cancelled',message:'execution cancelled'});
        assert.equal(events.length,count);
      }
      const bytes=Buffer.alloc(fs.fstatSync(fd).size);
      fs.readSync(fd,bytes,0,bytes.length,0);realReads++;
      assert.equal(bytes.toString(),events.join(''));
      return {events,output:bytes.toString()};
    }finally{fs.closeSync(fd);}
  };
  const normal=run();
  assert.equal(normal.output,row.stdout);
  for(let at=1;at<=normal.events.length;at++)assert.deepEqual(run(at).events,normal.events.slice(0,at));
  results.push({name:row.name,matched:true,cancellationPoints:normal.events.length});
}
const report={results,realWrites,realReads};
fs.writeFileSync('/tmp/charmap-classification-services.json',JSON.stringify(report,null,2));
console.log(JSON.stringify(report));

