import fs from 'node:fs';
import assert from 'node:assert/strict';
import {CodePointString} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/code-point-string.ts';
import {PythonRuntimeError} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/error.ts';
import {ExecutionBudget} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/execution-budget.ts';
import {RuntimeCharmap} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-charmap.ts';
import {RuntimeExceptionExecution} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-exception-execution.ts';
import {RuntimeTypeRegistry} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-type-registry.ts';
import {RuntimeValues} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-values.ts';
const results=[];
let reads=0,writes=0;
for(const stage of ['input','replacement'])for(const cancel of [false,true]){
  const fd=fs.openSync('/tmp/charmap-classification-boundary-output.txt','w+');
  const controller=new AbortController();
  const meter=new ExecutionBudget({maxSteps:100000,maxAllocatedBytes:1000000,signal:controller.signal});
  const values=new RuntimeValues(meter),types=new RuntimeTypeRegistry(values,{hash:()=>0n,equal:(a,b)=>a===b},meter);
  const exceptions=new RuntimeExceptionExecution(types,values,meter);
  const mapping=values.cell({}),input=CodePointString.fromString('A',meter),replacement=CodePointString.fromString('?',meter);
  const missing=exceptions.prepare(new PythonRuntimeError('KeyError','mapping failed'));
  let lookups=0,caught;
  const write=(text:string)=>{fs.writeSync(fd,text+'\n');fs.fsyncSync(fd);writes++;};
  const context={lookupSpecial:()=>mapping,call(){lookups++;if(stage==='replacement'&&lookups===1)return values.none;throw missing;},
    isException(error,name){const matches=exceptions.matches(error,name);write('classify');if(cancel)controller.abort();return matches;}};
  let rejected;
  try{
    new RuntimeCharmap(values,meter).encode(input,mapping,error=>{
      write('recover');
      rejected=exceptions.prepare(error);
      return {replacement:stage==='input'?Uint8Array.of(63):replacement,position:1,rejectReplacement(){write('reject');throw rejected;}};
    },context);
  }catch(error){caught=error;}
  if(cancel)assert.equal(caught?.reason,'cancelled');
  else if(stage==='replacement')assert.equal(caught,rejected);
  else assert.equal(caught,undefined);
  const bytes=Buffer.alloc(fs.fstatSync(fd).size);fs.readSync(fd,bytes,0,bytes.length,0);reads++;fs.closeSync(fd);
  const expected=stage==='input'?'classify\n'+(cancel?'':'recover\n'):'recover\nclassify\n'+(cancel?'':'reject\n');
  assert.equal(bytes.toString(),expected);
  results.push({stage,cancel,output:bytes.toString(),matched:true});
}
const report={results,reads,writes};
fs.writeFileSync('/tmp/charmap-classification-boundary.json',JSON.stringify(report,null,2));
console.log(JSON.stringify(report));

